import type { HTTPError } from "../../error.ts";

/** Build the RFC 9457 JSON body of an error; standard members win over extensions. */
export function problemDetailsBody(error: HTTPError, debug?: boolean): Record<string, unknown> {
  const legacy = error.toJSON();
  const unhandled = !!error.unhandled;
  return {
    ...(unhandled ? undefined : error.body),
    data: legacy.data,
    type: (!unhandled && error.type) || "about:blank",
    title: (!unhandled && error.statusText) || statusPhrase(error.status),
    status: error.status,
    detail: legacy.message,
    instance: unhandled ? undefined : error.instance,
    stack: debug && error.stack ? error.stack.split("\n").map((l) => l.trim()) : undefined,
  };
}

// RFC 9110 status phrases (deterministic, independent of the runtime)
const STATUS_PHRASES =
  "200OK,201Created,202Accepted,204No Content,206Partial Content," +
  "301Moved Permanently,302Found,303See Other,304Not Modified,307Temporary Redirect,308Permanent Redirect," +
  "400Bad Request,401Unauthorized,402Payment Required,403Forbidden,404Not Found," +
  "405Method Not Allowed,406Not Acceptable,408Request Timeout,409Conflict,410Gone," +
  "411Length Required,412Precondition Failed,413Content Too Large,414URI Too Long," +
  "415Unsupported Media Type,416Range Not Satisfiable,417Expectation Failed,418I'm a teapot," +
  "421Misdirected Request,422Unprocessable Content,423Locked,424Failed Dependency," +
  "425Too Early,426Upgrade Required,428Precondition Required,429Too Many Requests," +
  "431Request Header Fields Too Large,451Unavailable For Legal Reasons," +
  "500Internal Server Error,501Not Implemented,502Bad Gateway,503Service Unavailable," +
  "504Gateway Timeout,505HTTP Version Not Supported,507Insufficient Storage,508Loop Detected," +
  "511Network Authentication Required";

function statusPhrase(status: number): string {
  const entry = STATUS_PHRASES.split(",").find((e) => e.startsWith(`${status}`));
  return entry ? entry.slice(3) : "";
}

